export function GlassModal({title,onClose,children,className=''}:{title:string;onClose:()=>void;children:ReactNode;className?:string}){const modalRef=useRef<HTMLElement>(null);useEffect(()=>{const previous=document.activeElement as HTMLElement|null;const frame=requestAnimationFrame(()=>modalRef.current?.querySelector<HTMLElement>('button:not([disabled]),input:not([disabled]),select:not([disabled]),textarea:not([disabled]),a[href]')?.focus());return()=>{cancelAnimationFrame(frame);previous?.focus()}},[]);const trapFocus=(event:React.KeyboardEvent<HTMLElement>)=>{if(event.key==='Escape'){event.preventDefault();onClose();return}if(event.key!=='Tab')return;const focusable=Array.from(modalRef.current?.querySelectorAll<HTMLElement>('button:not([disabled]),input:not([disabled]),select:not([disabled]),textarea:not([disabled]),a[href]')??[]).filter(element=>element.getClientRects().length>0);if(!focusable.length){event.preventDefault();return}const first=focusable[0],last=focusable[focusable.length-1];if(event.shiftKey&&document.activeElement===first){event.preventDefault();last.focus()}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first.focus()}};return <div className="modal-backdrop" role="presentation" onMouseDown={e=>e.target===e.currentTarget&&onClose()}><motion.section ref={modalRef} onKeyDown={trapFocus} initial={{opacity:0,y:18,scale:.98}} animate={{opacity:1,y:0,scale:1}} exit={{opacity:0}} className={`glass-modal ${className}`} role="dialog" aria-modal="true" aria-label={title}><header><h2>{title}</h2><GlassButton aria-label="Close dialog" onClick={onClose}><X size={18}/></GlassButton></header>{children}</motion.section></div>}

