 useEffect(()=>{if(!session)return;const params=new URLSearchParams(window.location.search);const inviteToken=params.get('invite');const shareToken=params.get('share');const token=inviteToken??shareToken;if(!token)return;if(testMode&&!repo)return;if(!repo)return;let active=true;const url=new URL(window.location.href);url.searchParams.delete('share');url.searchParams.delete('invite');window.history.replaceState({},'',url);(async()=>{try{const result=inviteToken?await repo.acceptBoardEmailInvitation(inviteToken):await repo.requestBoardAccess(token);if(!active)return;setPendingBoardId(result.boardId);if(result.status==='requested'){setAccessState('pending');return}const boards=await repo.boards();const linked=boards.find(item=>item.id===result.boardId);if(!linked)throw new Error('Linked board is not available');const [nextLists,nextCards,sharing]=await Promise.all([repo.lists(linked.id),repo.cards(linked.id),repo.boardSharing(linked.id)]);if(!active)return;setBoard(linked);setLists(nextLists);setCards(nextCards);setCanManageMetadata(sharing.canManage);setBoardMembers(sharing.members);setShareNotice('');setAccessState('idle')}catch(e){if(active){setShareNotice((e as Error).message);setAccessState('error')}}})();return()=>{active=false}},[repo,session,testMode]);
