 const create=()=>{if(!adding||!newTitle.trim()||lists.find(list=>list.id===adding)?.kind==='ai')return;const listId=adding;const title=newTitle.trim();const lastPosition=Math.max(0,...cards.filter(c=>c.listId===listId).map(c=>c.position).filter(Number.isFinite));const card:Card={id:crypto.randomUUID(),listId,title,description:'',priority:'medium',labels:[],dueDate:null,completed:false,position:lastPosition+1,checklist:[],comments:[],customFields:{},dependencies:[],attachments:[]};setNewTitle('');setAdding(null);setQuery('');setPriority('all');setView('board');commit([...cards,card]);setScrollToCreatedCard({cardId:card.id,listId});if(repo&&!testMode)void runMutation(async()=>{await repo.createCard(board.id,listId,card.title,card.position)})};

